<?php ob_start(); ?><section class="section narrow"><p class="eyebrow">Planning</p><h1>Nouvelle reservation</h1><?php if (!empty($errors['global'])): ?><div class="alert"><?= htmlspecialchars($errors['global']) ?></div><?php endif; ?><form method="post" action="/reservations"><label>Salle<select name="salle_id" required><option value="">Choisir une salle</option><?php foreach ($salles as $salle): ?><option value="<?= $salle->id ?>" <?= (string) ($data['salle_id'] ?? '') === (string) $salle->id ? 'selected' : '' ?>><?= htmlspecialchars($salle->nom) ?> (<?= $salle->capacite ?> places)</option><?php endforeach; ?></select></label><label>Responsable<input name="responsable" value="<?= htmlspecialchars($data['responsable'] ?? '') ?>" required></label><label>Email<input type="email" name="email" value="<?= htmlspecialchars($data['email'] ?? '') ?>" required></label><label>Motif<textarea name="motif" required><?= htmlspecialchars($data['motif'] ?? '') ?></textarea></label><label>Debut<input type="datetime-local" name="date_debut" value="<?= htmlspecialchars($data['date_debut'] ?? '') ?>" required></label><label>Fin<input type="datetime-local" name="date_fin" value="<?= htmlspecialchars($data['date_fin'] ?? '') ?>" required></label><button class="button" type="submit">Confirmer</button></form></section><?php $content = ob_get_clean(); require dirname(__DIR__) . '/layout/base.php';